[CmdletBinding()]param([string]$Root='../..',[Parameter(Mandatory)][string]$RcTag)
Import-Module (Join-Path $PSScriptRoot 'Discovery.Release.psm1') -Force
if(-not $env:GITHUB_OUTPUT){throw 'GITHUB_OUTPUT is required'};if($RcTag -notmatch '^(.+)/v(\d+\.\d+\.\d+-rc\.\d+)$'){throw "Invalid RC tag '$RcTag'; expected <application-id>/vX.Y.Z-rc.N."};$appId=$Matches[1];$rcVersion=$Matches[2];$v=ConvertFrom-RcVersion $rcVersion;$final="$($v.major).$($v.minor).$($v.patch)";$finalTag="$appId/v$final";$tags=Get-ApplicationTags $Root $appId;if($tags -notcontains $RcTag){throw "RC tag '$RcTag' was not found."};if($tags -contains $finalTag){throw "Final tag '$finalTag' already exists."};$sha=Get-TagCommit $Root $RcTag;Add-Content -LiteralPath $env:GITHUB_OUTPUT -Value "app_id=$appId`nrc_version=$rcVersion`nfinal_version=$final`nfinal_tag=$finalTag`nrc_tag=$RcTag`nsource_sha=$sha" -Encoding utf8
